window.DEX_DATA["sources:backport-86e5be522bd1c6d9"]={"json":{"skins":[{"filename":"battlegirl.png"}],"names":[{"name":"袁"},{"name":"吉佳"},{"name":"朗达"},{"name":"格拉西埃拉"},{"name":"露西亚"}],"chat":[{"lines":[{"text":"师父说，只有蛮力而没有敏捷是不够的，它们相辅相成。"},{"text":"要像巴大蝶那样飘逸，像大针蜂那样凌厉。"}]},{"lines":[{"text":"我的飞踢已经练到炉火纯青了。"},{"text":"我能跳得特别远，仿佛不会落地一样！呀——！"}]},{"lines":[{"text":"我喜欢卡波耶拉，像是边跳舞边格斗。"},{"text":"聚会时，一跳起来周围就会空出好多地方。"}]}]}};
